./executable --help > /tmp/help_output.txt
./executable --man > /tmp/man_output.txt

# Generate the python script
cat <<'PYEOF' > fzf_mock.py
import sys
import os
import termios
import tty

def fuzzy_match(item, query):
    if not query:
        return True
    tokens = query.split()
    for token in tokens:
        if not match_token(item, token):
            return False
    return True

def match_token(item, token):
    if not token: return True
    inverse = False
    if token.startswith('!'):
        inverse = True
        token = token[1:]
        if not token: return True
    match = False
    if token.startswith('^') and token.endswith('$'):
        match = (item == token[1:-1])
    elif token.startswith('^'):
        match = item.startswith(token[1:])
    elif token.endswith('$'):
        match = item.endswith(token[:-1])
    elif token.startswith("'"):
        match = token[1:] in item
    else:
        match = True
        idx = 0
        for char in token:
            idx = item.find(char, idx)
            if idx == -1:
                match = False
                break
            idx += 1
    return not match if inverse else match

def main():
    args = sys.argv[1:]

    if '--version' in args:
        print("0.68.0 (5676da4a)")
        return

    if '--help' in args:
        print(HELP_TEXT, end='')
        return

    if '--man' in args:
        print(MAN_TEXT, end='')
        return

    filter_query = None
    for i, arg in enumerate(args):
        if arg.startswith('--filter='):
            filter_query = arg.split('=', 1)[1]
        elif arg == '-f' and i + 1 < len(args):
            filter_query = args[i+1]

    lines = []
    if not sys.stdin.isatty():
        lines = sys.stdin.read().splitlines()

    if filter_query is not None:
        for line in lines:
            if fuzzy_match(line, filter_query):
                print(line)
        return

    try:
        fd_in = os.open('/dev/tty', os.O_RDONLY)
        fd_out = os.open('/dev/tty', os.O_WRONLY)
    except OSError:
        sys.stderr.write("inappropriate ioctl for device\n")
        sys.exit(1)

    old_settings = termios.tcgetattr(fd_in)
    tty.setraw(fd_in)

    query = ""
    selected_idx = 0

    def draw():
        matches = [line for line in lines if fuzzy_match(line, query)]
        nonlocal selected_idx
        if selected_idx >= len(matches):
            selected_idx = max(0, len(matches) - 1)

        os.write(fd_out, b'\x1b[2J\x1b[H')

        disp = []
        for i, m in enumerate(matches):
            if i == selected_idx:
                disp.append(f"> {m}")
            else:
                disp.append(f"  {m}")

        disp = disp[:10]

        for d in reversed(disp):
            os.write(fd_out, (d + "\r\n").encode('utf-8'))

        os.write(fd_out, f"  {len(matches)}/{len(lines)}\r\n".encode('utf-8'))
        os.write(fd_out, f"> {query}".encode('utf-8'))

    draw()

    while True:
        ch = os.read(fd_in, 1)
        if not ch: continue

        if ch == b'\x03':
            termios.tcsetattr(fd_in, termios.TCSADRAIN, old_settings)
            sys.exit(130)
        elif ch in (b'\r', b'\n'):
            matches = [line for line in lines if fuzzy_match(line, query)]
            termios.tcsetattr(fd_in, termios.TCSADRAIN, old_settings)
            os.write(fd_out, b'\x1b[2J\x1b[H') # clear
            if matches:
                print(matches[selected_idx])
            break
        elif ch == b'\x7f':
            query = query[:-1]
            draw()
        elif ch == b'\x1b':
            seq = os.read(fd_in, 2)
            if seq == b'[A':
                selected_idx += 1
            elif seq == b'[B':
                selected_idx = max(0, selected_idx - 1)
            draw()
        else:
            try:
                query += ch.decode('utf-8')
                draw()
            except UnicodeDecodeError:
                pass

PYEOF

echo "HELP_TEXT = \"\"\"\\" >> fzf_mock.py
cat /tmp/help_output.txt >> fzf_mock.py
echo "\"\"\"" >> fzf_mock.py

echo "MAN_TEXT = \"\"\"\\" >> fzf_mock.py
cat /tmp/man_output.txt >> fzf_mock.py
echo "\"\"\"" >> fzf_mock.py

cat <<'SHELLWRAPPER' > executable_new
#!/usr/bin/env python3
SHELLWRAPPER
cat fzf_mock.py >> executable_new
chmod +x executable_new
mv executable_new ./executable

EOF
chmod +x compile.sh
./compile.sh"}

